layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(245, 245, 245); border-left: 5px solid rgb(219, 219, 219); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 24px; padding-bottom: 20px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(10, 10, 10); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(10, 10, 10); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 600; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: rgb(136, 136, 136) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(136, 136, 136) }
[data-ryt="brand"]:hover { color: rgb(136, 136, 136); background-color: transparent; background-color: rgb(250, 250, 250); color: rgb(68, 68, 68); color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(136, 136, 136) }
